func dueDateClass(status string) string {
	if status == "overdue" {
		return "font-medium text-red-600"
	}
	return "font-medium"
}

func activityRiskScoreBgClass(score int) string {
	switch {
	case score >= 12:
		return "bg-red-500"
	case score >= 6:
		return "bg-amber-400"
	default:
		return "bg-green-500"
	}
}

